import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p40_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matmul_scale_residual_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    double combined_scale);

torch::Tensor matmul_scale_residual_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    double combined_scale) {
    if (input.is_cuda()) {
        return matmul_scale_residual_forward_cuda(input, weight, bias, combined_scale);
    }
    // CPU fallback
    torch::Tensor out;
    if (bias.has_value() && bias.value().defined()) {
        out = at::addmm(bias.value(), input, weight.t(),
                        static_cast<float>(combined_scale),
                        static_cast<float>(combined_scale));
    } else {
        out = at::mm(input, weight.t()).mul_(combined_scale);
    }
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_scale_residual_forward", &matmul_scale_residual_forward,
          "scaled linear forward (CUDA fast path)",
          py::arg("input"), py::arg("weight"), py::arg("bias"), py::arg("combined_scale"));
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor matmul_scale_residual_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    double combined_scale) {

TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");

    auto input2d = input.contiguous();
    auto weight2d = weight.contiguous();
    auto weight_t = weight2d.t().contiguous();

    float alpha = static_cast<float>(combined_scale);

    if (bias.has_value() && bias.value().defined()) {
        // at::addmm: beta * bias + alpha * (input @ weight_t)
        // = combined_scale * bias + combined_scale * (input @ weight_t)
        // = combined_scale * (bias + input @ weight_t)-- the desired result
        return at::addmm(bias.value(), input2d, weight_t,
                         /*beta=*/alpha, /*alpha=*/alpha);
    } else {
        // No bias: combined_scale * (input @ weight_t)
        auto zero_bias = torch::zeros({weight2d.size(0)},
                                      input2d.options());
        return at::addmm(zero_bias, input2d, weight_t,
                         /*beta=*/0.0f, /*alpha=*/alpha);
    }
}
# <<<END_IMPROVE>>>
"""

